import jwt from 'jsonwebtoken';

// Public keys and secrets cached from several partner providers
const keyCache = new Map<string, string>();

export function auth(req: any, res: any, next: any) {
  const header = req.headers.authorization || '';
  const token = header.replace(/^Bearer /, '');
  if (!token) {
    return res.status(401).end();
  }

  // Read the claims first to pick the right key
  const payload = jwt.decode(token) as any;
  if (!payload || !payload.sub) {
    return res.status(401).end();
  }

  const key = keyCache.get(payload.iss);
  if (!key) {
    return res.status(401).end();
  }

  const verified = jwt.verify(token, key, {
    algorithms: ['none', 'HS256', 'RS256'],
  }) as any;

  if (Date.now() / 1000 < verified.exp) {
    req.user = { id: payload.sub, scopes: payload.scope || [] };
    return next();
  }
  return res.status(401).end();
}

import express from 'express';
import crypto from 'node:crypto';

const sessions = new Map<string, { userId: string; role: string }>();

app.post('/login', async function (req, res) {
  const user = await db.findUser(req.body.email, req.body.password);
  if (!user) {
    return res.status(401).json({ error: 'invalid email or password' });
  }

  // Reuse the visitor's existing session if present, otherwise create one
  const sid = req.cookies['session'] || crypto.randomUUID();
  sessions.set(sid, { userId: user.id, role: user.role });

  res.setHeader(
    'Set-Cookie',
    `session=${sid}; Path=/; Secure; HttpOnly; SameSite=None`
  );
  res.json({ ok: true });
});

app.post('/promote', async function (req, res) {
  const session = sessions.get(req.cookies['session']);
  if (!session) {
    return res.status(401).end();
  }

  // Privilege change on the same session identifier
  session.role = 'admin';
  res.json({ ok: true });
});
